    /// <summary>Allowed sizes for the heading – Defaults to `["xxs", "xs", "s", "m", "l", "xl"]`.</summary>
    /// <remarks>Macro option <c>caption.sizes</c>, released in 10.6.0.</remarks>
    [JsonPropertyName("sizes")] public List<string>? Sizes { get; set; }

    /// <summary>Optional heading level. Defaults to `1`.</summary>
    /// <remarks>Macro option <c>caption.level</c>, released in 10.6.0.</remarks>
    [JsonPropertyName("level")] public int? Level { get; set; }

    /// <summary>Optional class to use for the heading. Defaults to `"nhsuk-heading"`.</summary>
    /// <remarks>Macro option <c>caption.className</c>, released in 10.6.0.</remarks>
    [JsonPropertyName("className")] public string? ClassName { get; set; }

    /// <summary>Optional class prefix to use for the heading. Defaults to `"nhsuk-heading-"`.</summary>
    /// <remarks>Macro option <c>caption.classPrefix</c>, released in 10.6.0.</remarks>
    [JsonPropertyName("classPrefix")] public string? ClassPrefix { get; set; }

    /// <summary>HTML element for the heading component – for example, `"caption"`. Defaults to the `level` option prefixed with `"h"`.</summary>
    /// <remarks>Macro option <c>caption.element</c>, released in 10.6.0.</remarks>
    [JsonPropertyName("element")] public string? Element { get; set; }

    /// <summary>Upstream templates accept <c>true</c> here to mean "use the defaults".</summary>
    public static implicit operator TablesCaptionOptions(bool value) => value ? new() { IsTrue = true } : null!;

    /// <summary>Upstream templates accept a plain string here, used as <c>text</c>.</summary>
    public static TablesCaptionOptions FromShorthand(string value) => new() { Text = value, IsShorthand = true };
    public static implicit operator TablesCaptionOptions(string value) => FromShorthand(value);
}
